mapper.select:
SELECT r.role_id AS roleId, r.role_code AS roleCode, r.role_nm AS roleNm, NULL::varchar AS roleDc, CASE WHEN r.role_code = 'PLATFORM_ADMIN' THEN 1 WHEN r.role_code = 'TENANT_ADMIN' THEN 2 ELSE 3 END AS roleLevel, 'Y' AS tenantScoped, t.tenant_code AS tenantCode, r.use_at AS useAt, r.created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, r.updated_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId FROM tb_role r INNER JOIN tb_tenant t ON t.tenant_id = r.tenant_id WHERE 1=1
AND t.tenant_code = #{tenantCode}
ORDER BY roleLevel, roleCode

SELECT r.role_id AS roleId, r.role_code AS roleCode, r.role_nm AS roleNm, NULL::varchar AS roleDc, CASE WHEN r.role_code = 'PLATFORM_ADMIN' THEN 1 WHEN r.role_code = 'TENANT_ADMIN' THEN 2 ELSE 3 END AS roleLevel, 'Y' AS tenantScoped, t.tenant_code AS tenantCode, r.use_at AS useAt, r.created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, r.updated_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId FROM tb_role r INNER JOIN tb_tenant t ON t.tenant_id = r.tenant_id WHERE 1=1
AND t.tenant_code = #{tenantCode}
AND r.use_at = #{useAt}
AND r.role_code ILIKE '%' || #{searchKeyword} || '%'
AND r.role_nm ILIKE '%' || #{searchKeyword} || '%'
AND r.role_nm ILIKE '%' || #{searchKeyword} || '%'
ORDER BY roleLevel, roleCode OFFSET #{firstIndex} LIMIT #{recordCountPerPage}

SELECT COUNT(1) FROM tb_role r INNER JOIN tb_tenant t ON t.tenant_id = r.tenant_id WHERE 1=1
AND t.tenant_code = #{tenantCode}
AND r.use_at = #{useAt}
AND r.role_code ILIKE '%' || #{searchKeyword} || '%'
AND r.role_nm ILIKE '%' || #{searchKeyword} || '%'
AND r.role_nm ILIKE '%' || #{searchKeyword} || '%'

WITH RECURSIVE menu_tree AS ( SELECT m.menu_id, m.menu_code, m.parent_menu_id, m.menu_nm, m.menu_order, lpad(coalesce(m.menu_order, 0)::text, 5, '0') AS sort_path, 1 AS depth FROM tb_menu m WHERE m.parent_menu_id IS NULL UNION ALL SELECT c.menu_id, c.menu_code, c.parent_menu_id, c.menu_nm, c.menu_order, mt.sort_path || '-' || lpad(coalesce(c.menu_order, 0)::text, 5, '0') AS sort_path, mt.depth + 1 FROM tb_menu c INNER JOIN menu_tree mt ON c.parent_menu_id = mt.menu_id ) SELECT rmp.role_menu_permission_id AS roleMenuPermissionId, rmp.role_id AS roleId, r.role_code AS roleCode, rmp.menu_id AS menuId, m.menu_code AS menuCode, rmp.permission_id AS permissionId, p.permission_code AS permissionCode, 'Y' AS useAt, rmp.created_at AS frstRegistPnttm, 'SYSTEM' AS frstRegisterId, rmp.created_at AS lastUpdtPnttm, 'SYSTEM' AS lastUpdusrId, r.role_nm AS roleNm, mt.menu_nm AS menuNm, m.menu_url AS menuUrl, p.permission_nm AS permissionNm, CASE WHEN p.permission_code = 'PERM_WRITE' THEN 'write' ELSE 'read' END AS permissionLevel FROM tb_role_menu_permission rmp LEFT JOIN tb_role r ON rmp.role_id = r.role_id LEFT JOIN tb_tenant t ON r.tenant_id = t.tenant_id LEFT JOIN menu_tree mt ON rmp.menu_id = mt.menu_id LEFT JOIN tb_menu m ON rmp.menu_id = m.menu_id LEFT JOIN tb_permission p ON rmp.permission_id = p.permission_id WHERE 1=1
AND r.role_code = #{roleCode}
AND t.tenant_code = #{tenantCode}
AND m.menu_code = #{menuCode}
AND p.permission_code = #{permissionCode}
ORDER BY mt.sort_path

mapper.insert:
INSERT INTO tb_role_menu_permission ( role_id, menu_id, permission_id, created_at ) VALUES ( ( SELECT r.role_id FROM tb_role r WHERE r.role_code = #{roleCode}
AND r.tenant_id = ( SELECT tenant_id FROM tb_tenant WHERE tenant_code = #{tenantCode} LIMIT 1 )
ORDER BY r.role_id LIMIT 1 ), ( SELECT m.menu_id FROM tb_menu m WHERE m.menu_code = #{menuCode} ORDER BY m.menu_id LIMIT 1 ), ( SELECT p.permission_id FROM tb_permission p JOIN tb_role r ON r.tenant_id = p.tenant_id WHERE r.role_code = #{roleCode}
AND r.tenant_id = ( SELECT tenant_id FROM tb_tenant WHERE tenant_code = #{tenantCode} LIMIT 1 )
AND p.permission_code = #{permissionCode} ORDER BY p.permission_id LIMIT 1 ), now() ) ON CONFLICT (role_id, menu_id, permission_id) DO NOTHING

mapper.delete:
DELETE FROM tb_role_menu_permission
WHERE role_id IN (
    SELECT r.role_id
    FROM tb_role r
        INNER JOIN tb_tenant t ON t.tenant_id = r.tenant_id
    WHERE r.role_code = #{roleCode}

        AND t.tenant_code = #{tenantCode}

)
